// src/lib/institutional/decisions.ts
//
// PR-05 — Escalation + SLA Engine, PR-06 — Decision Engine, PR-07 —
// Delegation Engine.
//
// PR-05: an escalation is generated BY POLICY when an authority check is
// refused (bounds exceeded) or an SLA breaches — not by frontend code.
// Each escalation carries an explicit reason (PR-01 EscalationReason) so
// the principal sees WHY.
//
// PR-06: a decision is the durable record every consequential action
// produces. The case's state only moves through a decision; decisions
// are the institutional decision history. A decision pins actor +
// role_context + authority_source + the exact authority_ids that allowed
// it, so PR-11 audit can reconstruct "why did this happen".
//
// PR-07: the delegation engine is PR-04's delegation-aware authorize().
// An active, unrevoked, in-window delegation satisfies an authority
// policy that requires a role the delegatee does not directly hold. We
// do NOT add a parallel delegation table; the bounded grant already
// lives in `delegations` and the matching already runs in authorize().

import { query } from "@/lib/postgres";
import { logAuditEvent } from "@/lib/audit";
import { checkSoD } from "@/lib/institutional/sod";
import type {
  Actor,
  AuthorityDecision,
  AuthorityRequest,
  CaseState,
  DecisionRecord,
} from "@/lib/institutional/contracts";
import { authorize, transitionWorkflow } from "@/lib/institutional/workflow";
import { transitionCase } from "@/lib/institutional/cases";

// ── PR-05 · Escalation ────────────────────────────────────────────────────

export interface EscalationInput {
  caseId: string;
  /** PR-01 EscalationReason. */
  reason:
    | "SLA_BREACH" | "RISK_INCREASE" | "AUTHORITY_INSUFFICIENT"
    | "HIGH_IMPACT" | "REPEATED_REJECTION" | "CROSS_DOMAIN"
    | "MANUAL" | "EMERGENCY" | "POLICY_REQUIRED" | "CONFLICT_OF_INTEREST";
  severity?: "LOW" | "MEDIUM" | "HIGH" | "CRITICAL";
  /** 'authority_refused:<policy>' | 'sla_breach:<sla_id>' | 'manual:<user>'. */
  source?: string | null;
  /** Role + context the escalation targets; NULL = the domain ladder decides. */
  targetRole?: string | null;
  targetContext?: string | null;
  /** The authority ids that were considered (and why they failed). */
  authorityIds?: string[];
  deadline?: Date | string | null;
  evidence?: Record<string, unknown>;
  recommendedAction?: string | null;
  actor?: Actor;
}

export interface EscalationRow {
  id: string;
  case_id: string;
  reason: string;
  severity: string;
  source: string | null;
  target_role: string | null;
  target_context: string | null;
  status: string;
  created_at: string;
}

/**
 * Generate an escalation from policy. Called by the authority engine when
 * a check is refused, by the SLA sweeper when a due_at passes, by a risk
 * jump, or manually. The row is what PR-09's Executive Attention Engine
 * consumes — it is never produced by a button.
 */
export async function escalate(input: EscalationInput): Promise<EscalationRow> {
  const { rows } = await query<EscalationRow>(
    `INSERT INTO public.escalations
       (case_id, reason, severity, source, target_role, target_context,
        authority_ids, deadline, evidence, recommended_action, status)
     VALUES ($1,$2,$3,$4,$5,$6,$7::jsonb,$8,$9::jsonb,$10,'OPEN')
     RETURNING id, case_id, reason, severity, source, target_role, target_context, status, created_at`,
    [
      input.caseId,
      input.reason,
      input.severity ?? "MEDIUM",
      input.source ?? null,
      input.targetRole ?? null,
      input.targetContext ?? null,
      JSON.stringify(input.authorityIds ?? []),
      input.deadline ?? null,
      JSON.stringify(input.evidence ?? {}),
      input.recommendedAction ?? null,
    ],
  );
  const e = rows[0];

  // The case's own event stream records the escalation (PR-02 contract).
  const { addCaseEvent } = await import("@/lib/institutional/cases");
  await addCaseEvent(input.caseId, "escalated", {
    escalation_id: e.id,
    reason: e.reason,
    severity: e.severity,
    target: e.target_role,
  }, input.actor);

  await logAuditEvent({
    action: "case.escalated",
    userId: input.actor?.id ?? "system",
    userName: input.actor?.name ?? "system",
    userRole: input.actor?.role ?? "system",
    details: { case_id: input.caseId, escalation: e.id, reason: e.reason, severity: e.severity },
  } as any);

  return e;
}

/**
 * The SLA sweeper's entry: when a sla_instance's due_at passes, generate
 * the SLA_BREACH escalation. Called by the worker/cron, not by UI code.
 */
export async function breachSla(slaInstanceId: string, actor?: Actor): Promise<EscalationRow> {
  const { rows } = await query<{ id: string; case_id: string; sla_rule: string; due_at: string }>(
    `UPDATE public.sla_instances SET status = 'BREACHED', breached_at = now()
      WHERE id = $1 AND status = 'RUNNING'
      RETURNING id, case_id, sla_rule, due_at`,
    [slaInstanceId],
  );
  if (rows.length === 0) throw new Error(`sla instance ${slaInstanceId} not running`);
  const s = rows[0];
  return escalate({
    caseId: s.case_id,
    reason: "SLA_BREACH",
    source: `sla_breach:${s.id}`,
    severity: "HIGH",
    evidence: { sla_rule: s.sla_rule, due_at: s.due_at },
    recommendedAction: "Review the overdue case",
    actor,
  });
}

// ── PR-06 · Decision ──────────────────────────────────────────────────────

export interface RecordDecisionInput {
  caseId: string;
  /** The PR-01 StandardOperation. */
  operation:
    | "approve" | "reject" | "revoke" | "suspend" | "debar"
    | "override" | "escalate" | "delegate" | "lockdown"
    | "route_manager" | "route_deputy" | "route_principal";
  actor: Actor;
  /** The authority check that allowed this (from authorize()). */
  authority: AuthorityDecision;
  reason: string;
  evidence?: Record<string, unknown>;
  /** The impact preview computed before execution (PR-08 fills this in). */
  impact?: Array<{ system: string; effect: string; affectedCount?: number | null }>;
  /** The case state before / after (the workflow's from/to). */
  previousState?: string;
  resultingState?: string;
}

export interface DecisionRow {
  id: string;
  decision_no: string;
  case_id: string;
  operation: string;
  actor_id: string;
  actor_role: string;
  role_context: string;
  authority_source: string;
  authority_ids: string[];
  delegation_id: string | null;
  reason: string;
  impact: Array<{ system: string; effect: string; affectedCount?: number | null }>;
  previous_state: string | null;
  resulting_state: string | null;
  timestamp: string;
}

/**
 * Record a durable decision. Every consequential action (approve /
 * reject / revoke / suspend / debar / override) produces this. The
 * decision is the institutional decision history: it pins actor +
 * role_context + authority_source + the exact authority_ids that allowed
 * it, so PR-11 audit can reconstruct "why did this happen".
 *
 * A human-key decision_no (DEC-YYYY-NNNN) is minted per year so a
 * decision is referenceable by people, not just by uuid.
 */
export async function recordDecision(input: RecordDecisionInput): Promise<DecisionRow> {
  const year = new Date().getUTCFullYear();
  const { rows: cnt } = await query<{ n: number }>(
    `SELECT COUNT(*)::int AS n FROM public.decisions WHERE decision_no LIKE $1`,
    [`DEC-${year}-%`],
  );
  const n = (cnt[0]?.n ?? 0) + 1;
  const decisionNo = `DEC-${year}-${String(n).padStart(4, "0")}`;

  const authorityIds: string[] = input.authority.rule
    ? [input.authority.rule]
    : [];

  // PR-14 SoD gate: a decision that acts under a delegation must pass the
  // combined SoD check before it is recorded. The check is fail-closed:
  // an expired / out-of-scope / revoked grant blocks the decision.
  if (input.authority.authoritySource === "delegation") {
    const sod = checkSoD({
      actor: input.actor,
      requestOriginatorId: input.authority.delegationId ?? undefined,
      now: new Date(),
    });
    if (!sod.ok) {
      throw new Error(`SoD gate: ${sod.blockedBy.join("; ")}`);
    }
  }

  const { rows } = await query<DecisionRow>(
    `INSERT INTO public.decisions
       (decision_no, case_id, operation, actor_id, actor_role, role_context,
        authority_source, authority_ids, delegation_id, reason,
        evidence, impact, previous_state, resulting_state, timestamp)
     VALUES ($1,$2,$3,$4,$5,$6,$7,$8::jsonb,$9,$10,$11::jsonb,$12::jsonb,$13,$14, now())
     RETURNING *`,
    [
      decisionNo,
      input.caseId,
      input.operation,
      input.actor.id,
      input.actor.role,
      input.actor.roleContext,
      input.authority.authoritySource ?? "role",
      JSON.stringify(authorityIds),
      input.authority.delegationId ?? null,
      input.reason,
      JSON.stringify(input.evidence ?? {}),
      JSON.stringify(input.impact ?? []),
      input.previousState ?? null,
      input.resultingState ?? null,
    ],
  );
  const d = rows[0];

  // A decision that approves/rejects also moves the case lifecycle
  // (CREATED → OPEN → RESOLVED → CLOSED is owned by PR-02; the decision
  // is the durable record, not the state machine).
  if (input.operation === "approve" || input.operation === "reject") {
    await transitionCase({
      caseId: input.caseId,
      action: input.operation === "approve" ? "resolve" : "cancel",
      detail: { decision_no: d.decision_no, operation: input.operation },
      actor: input.actor,
    }).catch(() => {
      /* the case may already be terminal; the decision still stands */
    });
  }

  // The case's event stream records the decision.
  const { addCaseEvent } = await import("@/lib/institutional/cases");
  await addCaseEvent(input.caseId, "decision_recorded", {
    decision_no: d.decision_no,
    operation: input.operation,
    authority_source: d.authority_source,
  }, input.actor);

  await logAuditEvent({
    action: "decision.recorded",
    userId: input.actor.id,
    userName: input.actor.name ?? input.actor.id,
    userRole: input.actor.role,
    details: {
      case_id: input.caseId,
      decision_no: d.decision_no,
      operation: input.operation,
      authority_source: d.authority_source,
      authority_ids: authorityIds,
      delegation_id: d.delegation_id,
    },
  } as any);

  return d;
}

/** The durable DecisionRecord shape (PR-01) hydrated from a decisions row. */
export function toDecisionRecord(d: DecisionRow): DecisionRecord {
  return {
    decisionId: d.decision_no,
    caseId: d.case_id,
    actorId: d.actor_id,
    actorRole: d.actor_role,
    roleContext: d.role_context as DecisionRecord["roleContext"],
    authoritySource: d.authority_source as DecisionRecord["authoritySource"],
    decision: d.operation as DecisionRecord["decision"],
    reason: d.reason,
    impact: d.impact,
    timestamp: d.timestamp,
    correlationId: d.decision_no,
  };
}

// ── PR-05 + PR-06 · the institutional loop ───────────────────────────────

export interface InstitutionalTransition {
  /** The durable decision that moved the case (null when escalated). */
  decision: DecisionRow | null;
  /** True when the authority check was refused and an escalation was generated instead. */
  escalated: boolean;
  /** The escalation that was generated (null when the decision succeeded). */
  escalationId: string | null;
  /** The workflow state the case moved to (null when escalated). */
  resultingState: string | null;
}

/**
 * The full institutional loop: move a case through its workflow AND
 * record the durable decision that moved it. When the authority check is
 * refused, generate the escalation (PR-05) instead of moving; the case
 * stays put and the escalation is what PR-09 surfaces.
 *
 * This is the one entry point a migrated domain (PR-13) calls: it does
 * not reach for the state machine directly, it asks for a decision.
 */
export async function decideAndTransition(
  caseId: string,
  action: string,
  actor: Actor,
  definitionCode: string,
  bounds: Record<string, unknown> = {},
  reason: string = "manual",
  impact?: Array<{ system: string; effect: string; affectedCount?: number | null }>,
): Promise<InstitutionalTransition> {
  // 1. Authority check (PR-04). If refused → escalation (PR-05).
  const req: AuthorityRequest & Record<string, unknown> = {
    actorId: actor.id,
    role: actor.role,
    context: actor.roleContext,
    operation: action as AuthorityRequest["operation"],
    caseType: definitionCode as AuthorityRequest["caseType"],
    scope: "institution",
    authoritySource: "role",
    ...bounds,
  };
  let authority = await authorize(req);

  // Routing ops are workflow transitions, not authority-gated decisions.
  // They move a case to the next review state and are open to whoever
  // holds the current state's role. The terminal op (approve) is where
  // the authority question is actually asked.
  const isRouting = action === "route_manager" || action === "route_deputy" || action === "route_principal";
  if (isRouting && !authority.allowed) {
    authority = {
      allowed: true,
      rule: `routing_${action}`,
      authoritySource: "role",
    };
  }

  if (!authority.allowed) {
    const e = await escalate({
      caseId,
      reason: "AUTHORITY_INSUFFICIENT",
      severity: "HIGH",
      source: `authority_refused:${authority.rule}`,
      authorityIds: authorityIdsOf(authority),
      evidence: { bounds, reason: authority.reason },
      recommendedAction: "Review the escalation",
      actor,
    });
    // The workflow transition is NOT attempted — the case stays put.
    return { decision: null, escalated: true, escalationId: e.id, resultingState: null };
  }

  // 2. The workflow transition (PR-03).
  const res = await transitionWorkflow(caseId, action, actor, definitionCode, bounds);

  // 3. The durable decision (PR-06).
  const decision = await recordDecision({
    caseId,
    operation: action as RecordDecisionInput["operation"],
    actor,
    authority,
    reason,
    impact,
    previousState: res.fromState,
    resultingState: res.toState,
  });

  return { decision, escalated: false, escalationId: null, resultingState: res.toState };
}

function authorityIdsOf(a: AuthorityDecision): string[] {
  return a.rule ? [a.rule] : [];
}
